"""Self-signed DER trust anchors for GitHub hosts used by the updater."""

import binascii


# USERTrust ECC Certification Authority, valid through 2038-01-18.
_GITHUB_API_ROOT = ''

# ISRG Root X1, valid through 2035-06-04.
_GITHUB_RAW_ROOT = ''


def for_host(host):
  if host == 'api.github.com' or host.endswith('.github.com'):
    return binascii.a2b_base64(_GITHUB_API_ROOT)
  if host == 'raw.githubusercontent.com' or host.endswith('.githubusercontent.com'):
    return binascii.a2b_base64(_GITHUB_RAW_ROOT)
  raise ValueError('No pinned CA certificate for %s' % host)
